// EDITAR UNA VEZ tras importar: valores del despliegue que NO son secretos.
// Las claves privadas (GitHub, Claude, clave de servicio de Supabase, Gmail) van en credenciales de n8n, nunca aquí.
return [{ json: {
  github_repo: 'TU-USUARIO/meridiano-motor',                    // repositorio donde corre el motor (GitHub Actions)
  github_rama: 'main',
  supabase_url: 'https://xxxxxxxx.supabase.co',
  hoja_datos_id: 'ID-de-la-hoja-de-Google-Sheets',               // lo que va entre /d/ y /edit en la URL de la hoja
  panel_url: 'https://meridian-insight-atlas.lovable.app',
  correo_direccion: 'direccion@meridiano.com',
  correo_datos: 'datos@meridiano.com',                           // responsable de la hoja de datos (avisos de la carga)
  correo_privacidad: 'privacidad@meridiano.example',             // aparece en el pie de los correos (derechos de protección de datos)
  baja_url: 'http://localhost:5678/webhook/meridiano-baja',      // URL de producción del webhook de W8 (enlace de baja de los correos)
  modelo_ia: 'claude-sonnet-5-5',
  // MODO DEMO (datos ficticios): todos los correos van al buzón de pruebas, con el destinatario real en el asunto.
  // Los correos salen de la cuenta de Gmail conectada en n8n; el buzón de pruebas puede ser esa misma cuenta (con alias +demo).
  modo_demo: true,
  buzon_demo: 'TU-CUENTA+demo@gmail.com',
} }];

// ¿Qué hay que enviar?
//  · Webhook de Supabase (evento nuevo): solo la propuesta de ese evento, y solo si el evento es una aceptación.
//    Así dos aceptaciones seguidas no se envían dos veces.
//  · Lanzamiento a mano («Reintentar envíos pendientes»): todas las aceptadas que sigan sin enviar.
const wh = $('Propuesta aceptada en el panel');
if (wh.isExecuted) {
  return wh.all()
    .map(i => i.json.body || i.json)
    .filter(b => b.table === 'eventos_propuesta' && b.type === 'INSERT' && b.record && b.record.accion === 'aprobar')
    .map(b => ({ json: { filtro: `&id=eq.${Number(b.record.propuesta_id)}` } }));
}
return [{ json: { filtro: '' } }];

// Un correo por propuesta aceptada, con el TEXTO APROBADO (el que quedó congelado al pulsar «Aceptar»),
// maquetado con la identidad de Meridiano (misma paleta y tipografías que la web y el panel) y con pie de baja (H2).
// Bloqueos: contacto ficticio fuera del modo demo · contacto en la lista de exclusión · falta el enlace de baja.
const cfg = $('Configuración').first().json;
const filas = $input.all().map(i => i.json).filter(p => p && p.id);

const C = { ink: '#1B1712', paper: '#ECE5D3', paper2: '#E1D8BF', brass: '#C0902F', brassDark: '#8F6A22',
            teal: '#3E5C52', onInk: '#ECE5D3', onPaper: '#211D17', blanco: '#FBF8F1' };
const SERIF = "Fraunces, Georgia, 'Times New Roman', serif";
const SANS = "'Libre Franklin', 'Helvetica Neue', Arial, sans-serif";
const MONO = "'IBM Plex Mono', 'Courier New', monospace";
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const EYEBROW = { riesgo: 'Su cuenta en Meridiano', ampliacion: 'Propuesta para su marca', lead_nuevo: 'Primer contacto',
                  seguimiento: 'Seguimiento' };

// Párrafos del texto aprobado; las líneas que empiezan por «- » o «• » se maquetan como lista
function cuerpo(texto) {
  return String(texto || '').trim().split(/\n\s*\n/).map(bloque => {
    const lineas = bloque.split('\n');
    if (lineas.every(l => /^\s*[-•]\s+/.test(l)))
      return `<ul style="margin:0 0 16px;padding-left:20px;">${lineas.map(l =>
        `<li style="margin:0 0 6px;">${esc(l.replace(/^\s*[-•]\s+/, ''))}</li>`).join('')}</ul>`;
    return `<p style="margin:0 0 16px;">${lineas.map(esc).join('<br>')}</p>`;
  }).join('\n');
}

function html(p, enlaceBaja, asunto) {
  const demo = cfg.modo_demo ? `
  <tr><td style="background:${C.paper2};border-bottom:1px solid ${C.brassDark};padding:10px 32px;font-family:${MONO};font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${C.brassDark};">
    Correo de demostración · En real iría a ${esc(p.contacto_nombre)} &lt;${esc(p.contacto_email)}&gt;
  </td></tr>` : '';
  return `<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light only"><title>${esc(asunto)}</title>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,500;0,600;1,500&family=Libre+Franklin:wght@400;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
</head>
<body style="margin:0;padding:0;background:${C.paper};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.paper};">
<tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:${C.blanco};border:1px solid ${C.paper2};">
  <tr><td style="background:${C.ink};padding:22px 32px;">
    <span style="font-family:${SERIF};font-size:26px;font-weight:600;letter-spacing:.03em;color:${C.onInk};">MERID<em style="font-style:italic;font-weight:500;color:${C.brass};">I</em>ANO</span>
    <span style="font-family:${MONO};font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:${C.brass};padding-left:12px;">Departamento comercial</span>
  </td></tr>${demo}
  <tr><td style="padding:32px 32px 8px;">
    <div style="font-family:${MONO};font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:${C.teal};margin-bottom:10px;">&mdash;&nbsp; ${esc(EYEBROW[p.etiqueta] || 'Meridiano')}</div>
    <h1 style="margin:0 0 20px;font-family:${SERIF};font-weight:500;font-size:24px;line-height:1.15;color:${C.onPaper};">${esc(asunto)}</h1>
  </td></tr>
  <tr><td style="padding:0 32px 8px;font-family:${SANS};font-size:15px;line-height:1.6;color:${C.onPaper};">
${cuerpo(p.texto_aprobado)}
  </td></tr>
  <tr><td style="padding:8px 32px 28px;">
    <div style="border-top:1px solid ${C.brass};width:40px;margin:0 0 12px;"></div>
    <div style="font-family:${SERIF};font-size:17px;font-weight:500;color:${C.onPaper};">${esc(p.comercial_nombre)}</div>
    <div style="font-family:${SANS};font-size:13px;color:${C.teal};">Meridiano · Departamento comercial${p.comercial_correo ? ` · <a href="mailto:${esc(p.comercial_correo)}" style="color:${C.teal};">${esc(p.comercial_correo)}</a>` : ''}</div>
  </td></tr>
  <tr><td style="background:${C.paper2};padding:18px 32px;font-family:${SANS};font-size:11.5px;line-height:1.55;color:#5A5246;">
    Recibe este mensaje porque ${p.etiqueta === 'lead_nuevo' ? 'aceptó recibir información comercial de Meridiano' : 'su empresa mantiene una relación comercial con Meridiano'}.
    Meridiano trata sus datos de contacto para gestionar esa relación; puede ejercer sus derechos de acceso, rectificación, oposición y supresión escribiendo a ${esc(cfg.correo_privacidad || 'privacidad@meridiano.example')}.<br><br>
    Si no desea recibir más comunicaciones comerciales de Meridiano, puede
    <a href="${esc(enlaceBaja)}" style="color:${C.brassDark};font-weight:600;">darse de baja aquí</a>.
  </td></tr>
</table>
<div style="font-family:${MONO};font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:${C.brassDark};padding-top:14px;">Meridiano · Medio para el público senior · Caso de estudio ficticio</div>
</td></tr></table>
</body></html>`;
}

return filas.map(p => {
  const enlaceBaja = cfg.baja_url && p.token_baja ? `${cfg.baja_url}?t=${encodeURIComponent(p.token_baja)}` : null;
  const bloqueo = p.contacto_excluido ? 'El contacto se ha dado de baja de las comunicaciones comerciales'
    : (!cfg.modo_demo && p.contacto_ficticio) ? 'Contacto ficticio: no se envía fuera del modo demo'
    : !enlaceBaja ? 'Falta el enlace de baja (baja_url en Configuración o token del contacto): no se envía sin él'
    : null;
  const asunto = p.asunto_email || p.material_titulo || `Meridiano · ${p.razon_social}`;
  const aviso = cfg.modo_demo ? `[Correo de demostración. En real iría a ${p.contacto_nombre} <${p.contacto_email}>]\n\n` : '';
  return { json: {
    id: p.id, razon_social: p.razon_social, bloqueo,
    para: p.contacto_email,
    asunto,
    html: enlaceBaja ? html(p, enlaceBaja, asunto) : null,
    // Versión en texto (registro y lectores sin HTML)
    texto: aviso + p.texto_aprobado + `\n\n${p.comercial_nombre}\nMeridiano · Departamento comercial`
           + (enlaceBaja ? `\n\nSi no desea recibir más comunicaciones comerciales de Meridiano: ${enlaceBaja}` : ''),
  } };
});

// Solo se envían las propuestas que ESTA ejecución ha conseguido reservar en Supabase (reservar_envios).
// Si el aviso del panel y un reintento manual coinciden, la otra ejecución no recibe la reserva y no envía (H1).
const r = $input.first().json || {};
const reservadas = new Set((r.reservadas || []).map(Number));
return $('Preparar correo').all().filter(i => !i.json.bloqueo && reservadas.has(Number(i.json.id)));

// Resultado de cada envío de Gmail → registrar_envio en Supabase.
//  · Gmail confirma (id de mensaje)                → «enviada» con su id.
//  · Gmail rechaza de forma explícita (error 4xx) → «error_envio» con el motivo: el correo no salió y se puede reintentar.
//  · Respuesta ambigua (timeout, red, 5xx, vacía)  → NO se registra: la reserva queda en envios_sin_confirmar y dirección
//    la libera tras mirar Enviados en Gmail (el correo pudo salir; reintentarlo podría duplicarlo). Lo avisa
//    «Envíos sin confirmar» (w5_sin_confirmar.js), que usa la misma clasificación.
// Gmail devuelve un elemento por cada correo, en el mismo orden que «Solo reservados».
const enviados = $('Solo reservados').all().map(i => i.json);
const res = $input.all().map(i => i.json || {});
const AMBIGUO = /timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNABORTED|ECONNREFUSED|EAI_AGAIN|socket hang up|network|aborted/i;
function clasificar(r) {
  if ((r.id || r.threadId) && !r.error) return { tipo: 'ok' };
  const e = r.error || {};
  const msg = String(e.message || e.description || (typeof e === 'string' ? e : '') || '');
  const code = Number(e.httpCode || e.status || e.statusCode || (msg.match(/\b([45]\d\d)\b/) || [])[1] || 0);
  if (code >= 400 && code < 500 && !AMBIGUO.test(msg)) return { tipo: 'error', error: msg.slice(0, 400) || `Gmail: error ${code}` };
  return { tipo: 'ambiguo', error: (msg || 'Gmail no ha respondido').slice(0, 400) };
}
return enviados.map((p, k) => ({ p, c: clasificar(res[k] || {}), r: res[k] || {} }))
  .filter(x => x.c.tipo !== 'ambiguo')
  .map(({ p, c, r }) => ({ json: { p_propuesta_id: p.id, p_accion: 'registrar_envio', p_usuario: 'n8n',
    p_datos: c.tipo === 'ok' ? { ok: true, id_mensaje: r.id } : { ok: false, error: c.error } } }));

// Envíos con respuesta ambigua de Gmail (timeout, red, 5xx o sin respuesta): no se registran ni se reintentan solos.
// Aviso inmediato a dirección para que compruebe en Enviados si el correo salió y, si no, lo libere con liberar_envio(id).
const enviados = $('Solo reservados').all().map(i => i.json);
const res = $('Enviar al contacto').all().map(i => i.json || {});
const AMBIGUO = /timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNABORTED|ECONNREFUSED|EAI_AGAIN|socket hang up|network|aborted/i;
const ambiguo = r => {
  if ((r.id || r.threadId) && !r.error) return false;
  const e = r.error || {};
  const msg = String(e.message || e.description || (typeof e === 'string' ? e : '') || '');
  const code = Number(e.httpCode || e.status || e.statusCode || (msg.match(/\b([45]\d\d)\b/) || [])[1] || 0);
  return !(code >= 400 && code < 500 && !AMBIGUO.test(msg));
};
const dudosos = enviados.map((p, k) => ({ p, r: res[k] || {} })).filter(x => ambiguo(x.r));
if (!dudosos.length) return [];
const cfg = $('Configuración').first().json;
return [{ json: {
  para: cfg.correo_direccion,
  asunto: `Meridiano · ${dudosos.length} envío${dudosos.length === 1 ? '' : 's'} sin confirmar: revisar antes de reintentar`,
  texto: 'Gmail no ha confirmado ni rechazado estos envíos, así que el correo pudo salir o no. No se reintentan solos para ' +
    'no enviarlos dos veces.\n\n' +
    dudosos.map(({ p, r }) => `- Propuesta ${p.id} · ${p.razon_social} · para ${p.para}\n  Respuesta: ` +
      String((r.error && (r.error.message || r.error)) || 'sin respuesta').slice(0, 200)).join('\n') +
    '\n\nCompruebe la carpeta Enviados. Si el correo NO salió, libérelo en Supabase con: select liberar_envio(<id>); ' +
    'y vuelva a lanzar «Reintentar envíos pendientes» en W5. Si salió, márquelo como enviado desde el panel.',
} }];

// Propuestas que no se pueden enviar (contacto dado de baja, ficticio fuera del modo demo, sin enlace de baja):
// se registran como error_envio con el motivo, en una rama propia para que se registren aunque no haya nada que enviar.
return $input.all().map(i => i.json).filter(p => p.bloqueo).map(p => ({ json: {
  p_propuesta_id: p.id, p_accion: 'registrar_envio', p_usuario: 'n8n', p_datos: { ok: false, error: p.bloqueo } } }));
